/**
 * The marks a space may wear in place of its initials: 189 in nine families of 21, drawn for Chips
 * as folded paper lit from the upper left (Arjun chose it on 22 September 2026, and asked for
 * twice the 84 the library had, then for a family of people), rather than taken from a public set
 * — a bought set is a set everybody else has, and it arrives with a licence to carry and a
 * dependency to bump.
 *
 * The lit side is white, the side turned away is the ground mixed into white, and a detail is a
 * hole cut through to the ground: six paints, one light, so the set reads as one hand's. `Mark`
 * draws them. The mocks and the reasoning are `docs/proposals/space-faces-mocks.html`.
 *
 * The 84 names the library had before are all here, so every saved face keeps its mark and is
 * redrawn; the other 105 are new. A name is the wire's (`/v1/me/space-icons` stores it), so a mark
 * is never renamed, only redrawn.
 *
 * The phone keeps the same table in `apps/mobile/src/ui/marks.ts`, and its `marks.vitest.ts`
 * reads this file and fails on any difference. Edit both, or neither.
 */

/**
 * What a layer is painted with. Each paint is worked out from the ground, so no mark has a colour
 * of its own.
 */
export type Paint =
  /** White: the side of the paper facing the light. */
  | "face"
  /** The ground mixed a quarter into white: the side turned away, the fold. */
  | "shade"
  /** The ground mixed a little over half into white: detail laid on a white face. */
  | "deep"
  /** White at 45%: things behind — a far peak, steam, stars. Never on top of paper. */
  | "far"
  /** White at 16%: a halo, drawn first. Dropped when the face is small. */
  | "air"
  /** The ground itself: a hole cut through the paper. */
  | "cut";

/** How a layer is drawn, beyond being filled. */
export interface LayerOptions {
  /** A round-capped stroke this wide in place of a fill. Under 1.05 it is dropped when small. */
  readonly stroke?: number;
  /** A fill's corners softened by a stroke of its own paint this wide. */
  readonly soften?: number;
  /** An SVG transform, in the mark's box. */
  readonly transform?: string;
  /**
   * Only part of the layer: right of a line (`right`), past the diagonal x + y = n that is the
   * fold (`fold`), or inside a path (`path`).
   */
  readonly clip?:
    | readonly ["right", number]
    | readonly ["fold", number]
    | readonly ["path", string];
}

export type Layer = readonly [Paint, string] | readonly [Paint, string, LayerOptions];

/** A mark: its layers, back to front, in a 24-point box. */
export type Mark = readonly Layer[];

/** Every mark is drawn in a 24-by-24 box. */
export const MARK_BOX = 24;

/**
 * How much of the face's side the mark takes: two thirds, with the paper's air round it. A mark
 * is drawn in the face's own coordinates rather than scaled into them (see the renderer), so the
 * cut paint lines up with the ground behind it to the pixel.
 */
export const MARK_SCALE = 0.66;

/** Below this side a face drops its halo and its hairlines, which blur into grey at 28 points. */
export const SMALL_FACE = 36;

